import kotlinx.atomicfu.AtomicInt
import kotlinx.atomicfu.atomic

private val refs = AtomicInt(0)

fun tryAcquire(): Boolean = refs.compareAndSet(0, 1)

// atomicfu types are inline classes: no allocation, and they compile to real
// atomics on Kotlin/Native and JS as well as the JVM
fun refDown() { refs.decrementAndGet() }

